import Image from 'next/image'; import Link from 'next/link'; import {giftGuides} from '@/data/gifts'; import {articles} from '@/data/articles'; import {GiftCard} from '@/components/GiftCard'; import {ArticleCard} from '@/components/ArticleCard'; import {seasonalGuides} from '@/data/seasonal';
export default function Home(){return <><section className="hero"><div className="container hero-grid"><div><span className="eyebrow">Gift ideas, thoughtfully curated</span><h1>Find a gift they&rsquo;ll actually love.</h1><p>Discover practical, personal and memorable gift ideas for the people who matter most.</p><Link className="button" href="/gifts-for-women">Explore gift guides</Link></div><div className="hero-art"><Image src="/images/gifts-for-women.jpg" alt="Gift ideas for women" fill priority sizes="(max-width: 900px) 100vw, 50vw"/></div></div></section><section className="section"><div className="container"><div className="section-head"><span className="eyebrow">Popular guides</span><h2>Start with who you&rsquo;re shopping for</h2></div><div className="guide-grid">{giftGuides.filter(g=>g.category==='Evergreen').slice(0,9).map(g=><GiftCard key={g.slug} guide={g}/>)}</div></div></section><section className="section soft"><div className="container"><div className="section-head"><span className="eyebrow">What&rsquo;s coming up</span><h2>Seasonal gift inspiration</h2><p className="section-note">Plan ahead for the moments people shop for most.</p></div><div className="seasonal-mini-grid">{seasonalGuides.slice(0,6).map(s=><Link href={`/seasonal/${s.slug}`} key={s.slug}><span>{s.month}</span><strong>{s.name}</strong><small>{s.date}</small></Link>)}</div><Link className="text-link" href="/seasonal">See all seasonal guides →</Link></div></section><section className="section"><div className="container"><div className="section-head"><span className="eyebrow">From the journal</span><h2>Helpful gift advice</h2></div><div className="article-grid">{articles.map(a=><ArticleCard key={a.slug} article={a}/>)}</div></div></section></>}
